ts // 2\n                    )\n                ):\n                    self.append(CutWire(), [num_qubits // 2])\n                if use_cut and layer < depth - 1 and layer_parity == 1:\n                    if qubit == num_qubits // 2:\n                        self.append(CutWire(), [qubit])\n            for qubit in range(num_qubits):\n                self.p(phis[qubit], qubit)\n'})}),"\n",(0,a.jsx)(s.h2,{id:"part-i-small-scale-example",children:"Teil I. Kleines Beispiel"}),"\n",(0,a.jsx)(s.h3,{id:"step-1-map-classical-inputs-to-a-quantum-problem",children:"Schritt 1: Klassische Eingaben auf ein Quantenproblem abbilden"}),"\n",(0,a.jsxs)(s.p,{children:["Zun\xe4chst erstellen wir einen Template-Circuit ohne konkrete Parameterwerte. Wir f\xfcgen auch Platzhalter namens ",(0,a.jsx)(s.code,{children:"CutWire"})," ein, um die Position der Schnitte zu markieren. F\xfcr das kleine Beispiel verwenden wir einen 10-Qubit-MBL-Circuit."]}),"\n",(0,a.jsx)(s.pre,{children:(0,a.jsx)(s.code,{className:"language-python",children:'num_qubits = 10\ndepth = 2\nmbl = MBLChainCircuit(num_qubits, depth)\nmbl.draw("mpl", fold=-1)\n'})}),"\n",(0,a.jsx)(s.p,{children:(0,a.jsx)(s.img,{src:"/docs/images/tutorials/wire-cutting/extracted-outputs/9c7939a1-6b70-4dad-b873-5f34d67551c4-0.avif",alt:"Output of the previous code cell"})}),"\n",(0,a.jsxs)(s.p,{children:["Zur Erinnerung: Wir m\xf6chten den Erwartungswert der Observablen ",(0,a.jsxs)(s.span,{className:"katex",children:[(0,a.jsx)(s.span,{className:"katex-mathml",children:(0,a.jsx)(s.math,{xmlns:"http://www.w3.org/1998/Math/MathML",children:(0,a.jsxs)(s.semantics,{children:[(0,a.jsxs)(s.mrow,{children:[(0,a.jsxs)(s.mfrac,{children:[(0,a.jsx)(s.mn,{children:"1"}),(0,a.jsx)(s.mi,{children:"n"})]}),(0,a.jsxs)(s.msubsup,{children:[(0,a.jsx)(s.mo,{children:"\u2211"}),(0,a.jsxs)(s.mrow,{children:[(0,a.jsx)(s.mi,{children:"i"}),(0,a.jsx)(s.mo,{children:"="}),(0,a.jsx)(s.mn,{children:"1"})]}),(0,a.jsx)(s.mi,{children:"n"})]}),(0,a.jsxs)(s.msub,{c